"""Схема базы отчётов (SQLite)."""
import sqlite3
from pathlib import Path

SCHEMA = """
CREATE TABLE clubs (
    id INTEGER PRIMARY KEY,
    name TEXT NOT NULL,
    opened_at TEXT NOT NULL
);
CREATE TABLE trainers (
    id INTEGER PRIMARY KEY,
    club_id INTEGER NOT NULL,
    name TEXT NOT NULL
);
CREATE TABLE persons (
    id INTEGER PRIMARY KEY,
    club_id INTEGER NOT NULL,
    created_at TEXT NOT NULL
);
CREATE TABLE visits (
    id INTEGER PRIMARY KEY,
    person_id INTEGER NOT NULL,
    club_id INTEGER NOT NULL,
    visit_date TEXT NOT NULL,
    visit_type TEXT NOT NULL            -- regular | trial | guest_pass
);
CREATE TABLE sales (
    id INTEGER PRIMARY KEY,
    club_id INTEGER NOT NULL,
    person_id INTEGER,                  -- у продаж бара покупатель неизвестен
    sale_date TEXT NOT NULL,
    kind TEXT NOT NULL,                 -- membership | personal_training | bar
    amount_kop INTEGER NOT NULL,
    channel TEXT NOT NULL CHECK (channel IN ('own', 'partner'))
);
CREATE TABLE sessions (
    id INTEGER PRIMARY KEY,
    club_id INTEGER NOT NULL,
    trainer_id INTEGER NOT NULL,
    person_id INTEGER NOT NULL,
    session_date TEXT NOT NULL,
    sale_id INTEGER NOT NULL
);
"""


def connect(path: str | Path = ":memory:") -> sqlite3.Connection:
    return sqlite3.connect(path)


def create_schema(conn: sqlite3.Connection) -> None:
    conn.executescript(SCHEMA)

"""Работа с деньгами.

Внутри системы суммы хранятся в копейках (int), чтобы не ловить ошибки округления float.
В рубли переводим только на выходе отчёта.
"""
from decimal import ROUND_HALF_UP, Decimal


def to_kopecks(value: str) -> int:
    """'1234.50' -> 123450"""
    return int((Decimal(value) * 100).quantize(Decimal("1"), rounding=ROUND_HALF_UP))


def to_rubles(kopecks: int) -> float:
    """123450 -> 1234.5"""
    return round(kopecks / 100, 2)


def split_evenly(total: int, parts: int) -> list[int]:
    """Делит сумму в копейках на parts частей. Лишние копейки достаются первым частям."""
    if parts <= 0:
        raise ValueError("parts must be positive")
    base, rest = divmod(total, parts)
    return [base + (1 if i < rest else 0) for i in range(parts)]

import unittest

from fitstat.reports import club_monthly_report, network_monthly_report, trainer_monthly_report
from tests.helpers import demo_db


class ClubReportTest(unittest.TestCase):
    def setUp(self):
        self.conn, self.cfg, _ = demo_db()

    def test_club_may(self):
        report = club_monthly_report(self.conn, self.cfg, 1, "2026-05")
        self.assertEqual(report["revenue"], 11750.5)
        self.assertEqual(report["revenue_own"], 8250.0)
        self.assertEqual(report["visits"], 4)
        self.assertEqual(report["active_members"], 2)
        self.assertEqual(report["pt_sessions"], 1)
        self.assertEqual(report["pt_revenue"], 2000.0)

    def test_empty_month(self):
        report = club_monthly_report(self.conn, self.cfg, 2, "2026-03")
        self.assertEqual(report["revenue"], 0.0)
        self.assertEqual(report["visits"], 0)


class TrainerReportTest(unittest.TestCase):
    def setUp(self):
        self.conn, self.cfg, _ = demo_db()

    def test_trainer_may(self):
        report = trainer_monthly_report(self.conn, self.cfg, 1, "2026-05")
        self.assertEqual(report["sessions"], 1)
        self.assertEqual(report["pt_revenue"], 2000.0)

    def test_trainer_without_sessions(self):
        report = trainer_monthly_report(self.conn, self.cfg, 2, "2026-05")
        self.assertEqual(report["sessions"], 0)
        self.assertEqual(report["pt_revenue"], 0.0)


class NetworkReportTest(unittest.TestCase):
    def setUp(self):
        self.conn, self.cfg, _ = demo_db()

    def test_closed_club_excluded(self):
        report = network_monthly_report(self.conn, self.cfg, "2026-05")
        self.assertEqual(report["clubs_count"], 1)
        self.assertEqual(report["revenue"], 11750.5)
        self.assertEqual(report["visits"], 4)

    def test_club_open_before_closing(self):
        report = network_monthly_report(self.conn, self.cfg, "2026-04")
        self.assertEqual(report["clubs_count"], 2)
        self.assertEqual(report["revenue"], 100.0)


if __name__ == "__main__":
    unittest.main()

import unittest

from fitstat.money import split_evenly, to_kopecks, to_rubles
from tests.helpers import demo_db


class ImporterTest(unittest.TestCase):
    def setUp(self):
        self.conn, self.cfg, self.counts = demo_db()

    def test_row_counts(self):
        self.assertEqual(
            self.counts,
            {"clubs": 2, "trainers": 3, "persons": 4, "visits": 6, "sales": 7, "sessions": 2},
        )

    def test_partner_channel_is_normalized(self):
        channel = self.conn.execute("SELECT channel FROM sales WHERE id = 2").fetchone()[0]
        self.assertEqual(channel, "partner")

    def test_amount_in_kopecks(self):
        amount = self.conn.execute("SELECT amount_kop FROM sales WHERE id = 2").fetchone()[0]
        self.assertEqual(amount, 350050)

    def test_bar_sale_without_person(self):
        person = self.conn.execute("SELECT person_id FROM sales WHERE id = 3").fetchone()[0]
        self.assertIsNone(person)


class MoneyTest(unittest.TestCase):
    def test_round_trip(self):
        self.assertEqual(to_kopecks("1234.50"), 123450)
        self.assertEqual(to_rubles(123450), 1234.5)

    def test_split_evenly(self):
        self.assertEqual(split_evenly(1001, 2), [501, 500])
        self.assertEqual(sum(split_evenly(1000, 3)), 1000)


if __name__ == "__main__":
    unittest.main()

